#!/usr/bin/env python3
import subprocess
import re

def get_registry_value(hive_file, key_path, value_name=None):
    command = f"hivexsh -f {hive_file}"
    if value_name:
        command += f" -c 'cd {key_path}' -c 'get {value_name}'"
    else:
        command += f" -c 'cd {key_path}' -c 'ls'"

    try:
        result = subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return result.stdout.strip()
    except Exception as e:
        return f"Error: {str(e)}"

# Get the hostname from SYSTEM hive
system_file = "/home/ctfplayer/ctf_files/SYSTEM"
hostname_key = "\\ControlSet001\\Control\\ComputerName\\ComputerName"
hostname_value = get_registry_value(system_file, hostname_key, "ComputerName")

print(f"Hostname: {hostname_value}")

