from Registry import Registry

def get_computer_name():
    try:
        system_hive = Registry.Registry('/home/ctfplayer/ctf_files/SYSTEM')

        # Navigate to the ControlSet001\Control\ComputerName\ComputerName key
        computer_name_key = system_hive.open('ControlSet001\\Control\\ComputerName\\ComputerName')

        # Get the ComputerName value
