from Registry import Registry
import os

def check_system_hive():
    system_path = '/home/ctfplayer/ctf_files/SYSTEM'

    # Check if file exists
    if not os.path.exists(system_path):
        print(f"File {system_path} does not exist")
        return

    try:
        system_hive = Registry.Registry(system_path)

        # Try different paths for hostname
        paths = [
            'ControlSet001\\Control\\ComputerName\\ComputerName',
            'ControlSet001\\Control\\ComputerName\\ActiveComputerName',
            'ControlSet001\\services\\Tcpip\\Parameters',
            'Select'
        ]

        for path in paths:
            try:
                key = system_hive.open(path)
                print(f"\nKey: {path}")
                for value in key.values():
                    print(f"  {value.name()}: {value.value()}")
            except Exception as e:
                print(f"Could not open {path}: {e}")

    except Exception as e:
        print(f"Error opening registry: {e}")

if __name__ == "__main__":
    check_system_hive()

#!/usr/bin/env python3
import sys
from Registry import Registry

def print_key_values(reg, key_path):
    try:
        key = reg.open(key_path)
        print(f"\nKey: {key_path}")
        print("-" * 50)
        for value in key.values():
            print(f"{value.name()}: {value.value()}")
    except Registry.RegistryKeyNotFoundException:
        print(f"Key not found: {key_path}")

def print_subkeys(reg, key_path):
    try:
        key = reg.open(key_path)
        print(f"\nSubkeys under {key_path}:")
        print("-" * 50)
        for subkey in key.subkeys():
            print(subkey.name())
    except Registry.RegistryKeyNotFoundException:
        print(f"Key not found: {key_path}")

def find_timezone_info(reg):
    try:
        key = reg.open("Microsoft\\Windows NT\\CurrentVersion\\Time Zones")
        print(f"\nFound Time Zones:")
        print("-" * 50)

        # Get the active timezone from SYSTEM hive
        system_reg = Registry.Registry("/home/ctfplayer/ctf_files/SYSTEM")
        try:
            tz_key = system_reg.open("ControlSet001\\Control\\TimeZoneInformation")
            active_tz = None
            for value in tz_key.values():
                if value.name() == "TimeZoneKeyName":
                    active_tz = value.value()
                    break

            print(f"Active TimeZone: {active_tz}")

            # If we found the active timezone, get more info about it
            if active_tz:
                try:
                    active_tz_key = key.open(active_tz)
                    print(f"\nActive Timezone Details ({active_tz}):")
                    print("-" * 50)
                    for value in active_tz_key.values():
                        print(f"{value.name()}: {value.value()}")
                except Registry.RegistryKeyNotFoundException:
                    print(f"Could not find details for timezone: {active_tz}")

        except Registry.RegistryKeyNotFoundException:
            print("Could not find TimeZoneInformation in SYSTEM hive")

    except Registry.RegistryKeyNotFoundException:
        print("Could not find Time Zones registry key")

def find_region_info(reg):
    # Check various registry paths for region information
    paths = [
        "Microsoft\\Windows NT\\CurrentVersion",
        "Microsoft\\Windows\\CurrentVersion\\Setup\\OOBE",
        "Control Panel\\International",
        "Microsoft\\Windows\\CurrentVersion\\GeoLocation",
        "Microsoft\\Windows NT\\CurrentVersion\\LanguagePack",
        "Microsoft\\Windows NT\\CurrentVersion\\International",
        "Microsoft\\Windows\\CurrentVersion\\Globalization",
    ]

    for path in paths:
        print_key_values(reg, path)

if __name__ == "__main__":
    software_hive = "/home/ctfplayer/ctf_files/SOFTWARE"

    print(f"Analyzing registry hive: {software_hive}")
    reg = Registry.Registry(software_hive)

    # Find general information
    find_region_info(reg)

    # Find timezone information
    find_timezone_info(reg)

    # Look at specific locale keys
    print_key_values(reg, "Microsoft\\Windows NT\\CurrentVersion\\ProfileList")
    print_key_values(reg, "Microsoft\\Windows NT\\CurrentVersion\\Perflib")

    # Check for NLS settings which might include language settings
    print_subkeys(reg, "Microsoft\\Windows NT\\CurrentVersion\\Perflib")

    print("\nRegistry analysis complete.")

#!/usr/bin/env python3
import sys
from Registry import Registry

def analyze_timezone(system_hive):
    reg = Registry.Registry(system_hive)

    # Try different potential locations for TimeZone information
    tz_paths = [
        "ControlSet001\\Control\\TimeZoneInformation",
        "CurrentControlSet\\Control\\TimeZoneInformation",
        "Select\\Current",
        "ControlSet001\\Control\\Nls\\Language"
    ]

    for path in tz_paths:
        try:
            key = reg.open(path)
            print(f"\nTimeZone Information from {path}:")
            print("-" * 60)
            for value in key.values():
                print(f"{value.name()}: {value.value()}")
        except Registry.RegistryKeyNotFoundException:
            print(f"Key not found: {path}")

    # Try to get the Active ControlSet
    try:
        select_key = reg.open("Select")
        current_cs = None
        for value in select_key.values():
            if value.name() == "Current":
                current_cs = value.value()
                print(f"\nActive ControlSet: ControlSet00{current_cs}")

        if current_cs:
            active_cs_path = f"ControlSet00{current_cs}\\Control\\TimeZoneInformation"
            try:
                key = reg.open(active_cs_path)
                print(f"\nTimeZone Information from active ControlSet:")
                print("-" * 60)
                for value in key.values():
                    print(f"{value.name()}: {value.value()}")
            except Registry.RegistryKeyNotFoundException:
                print(f"Key not found: {active_cs_path}")
    except Registry.RegistryKeyNotFoundException:
        print("Could not find Select key to determine active ControlSet")

if __name__ == "__main__":
    system_hive = "/home/ctfplayer/ctf_files/SOFTWARE"
    if len(sys.argv) > 1:
        system_hive = sys.argv[1]

    print(f"Analyzing TimeZone information from: {system_hive}")
    analyze_timezone(system_hive)

    # Also check SYSTEM hive
    system_hive = "/home/ctfplayer/ctf_files/SYSTEM"
    print(f"\nAnalyzing TimeZone information from: {system_hive}")
    analyze_timezone(system_hive)

