from Registry import Registry

def explore_key_recursive(reg, key_path, depth=0, max_depth=2):
    if depth > max_depth:
        return

    try:
        key = reg.open(key_path)
        print(f"{'  ' * depth}Key: {key_path}")

        # Print values
        for value in key.values():
            try:
                print(f"{'  ' * (depth+1)}Value: {value.name()} = {value.value()}")
            except Exception as e:
                print(f"{'  ' * (depth+1)}Value: {value.name()} (Error reading value: {str(e)})")

        # Recursively explore subkeys
        for subkey in key.subkeys():
            explore_key_recursive(reg, f"{key_path}\\{subkey.name()}", depth + 1, max_depth)

    except Registry.RegistryKeyNotFoundException:
        print(f"Key not found: {key_path}")

def check_specific_locales(reg):
    # Common paths for locale and regional settings
    locale_paths = [
        "Microsoft\\Windows NT\\CurrentVersion",
        "Control Panel\\International",
        "Microsoft\\Windows\\CurrentVersion\\GeoID",
        "Microsoft\\Windows\\CurrentVersion\\Globalization",
        "Microsoft\\Windows NLS",
        "Microsoft\\Windows\\CurrentVersion\\International",
        "Microsoft\\Windows NT\\CurrentVersion\\GRE_Initialize\\Locale",
        "Microsoft\\Windows NT\\CurrentVersion\\ProfileList"
    ]

    for path in locale_paths:
        try:
            explore_key_recursive(reg, path, max_depth=1)
            print("\n" + "-" * 60 + "\n")
        except Exception as e:
            print(f"Error exploring {path}: {str(e)}")

if __name__ == "__main__":
    software_hive = "/home/ctfplayer/ctf_files/SOFTWARE"

    print(f"Analyzing locale and region information from: {software_hive}")
    reg = Registry.Registry(software_hive)

    # Check for specific timezone and locale information
    check_specific_locales(reg)

    # Specifically check Control Panel International
    print("Specially checking Control Panel\\International:")
    try:
        key_path = "Microsoft\\Windows\\CurrentVersion\\Control Panel\\International"
        explore_key_recursive(reg, key_path, max_depth=1)
    except Exception as e:
        print(f"Error: {str(e)}")

    print("\nChecking alternative international path:")
    try:
        key_path = "Microsoft\\Windows\\CurrentVersion\\International"
        explore_key_recursive(reg, key_path, max_depth=1)
    except Exception as e:
        print(f"Error: {str(e)}")

    # Also check Windows Geographic Location
    print("\nChecking Windows Geographic Location:")
    try:
        key_path = "Microsoft\\Windows NT\\CurrentVersion\\ProfileList"
        explore_key_recursive(reg, key_path, max_depth=1)
    except Exception as e:
        print(f"Error: {str(e)}")

