import os
from Registry import Registry

def analyze_registry_for_region():
    """Analyze Windows registry hives for region/locale information"""
    print("Analyzing Windows registry hives for region and locale information...")

    # Path to registry hives
    software_hive = "/home/ctfplayer/ctf_files/SOFTWARE"
    system_hive = "/home/ctfplayer/ctf_files/SYSTEM"

    # Dictionary to store all region-related information
    region_info = {}

    # Check SOFTWARE hive
    if os.path.exists(software_hive):
        reg = Registry.Registry(software_hive)

        # Common registry paths for region/locale information
        paths_to_check = [
            r"Microsoft\Windows NT\CurrentVersion",
            r"Control Panel\International",
            r"Microsoft\Windows\CurrentVersion\GeoID",
            r"Microsoft\Windows\CurrentVersion\International",
            r"Microsoft\Windows\CurrentVersion\Globalization"
        ]

        for path in paths_to_check:
            try:
                key = reg.open(path)
                print(f"\nChecking {path}:")
                for value in key.values():
                    name = value.name()
                    if any(keyword in name.lower() for keyword in ["region", "location", "country", "locale", "time", "zone", "geo", "nation"]):
                        try:
                            region_info[f"{path}\\{name}"] = value.value()
                            print(f"  Found: {name} = {value.value()}")
                        except Exception as e:
                            print(f"  Error reading {name}: {str(e)}")

                # Check subkeys for one level
                for subkey in key.subkeys():
                    try:
                        subkey_path = f"{path}\\{subkey.name()}"
                        if any(keyword in subkey.name().lower() for keyword in ["region", "location", "country", "locale", "time", "zone", "geo", "nation"]):
                            print(f"\nChecking {subkey_path}:")
                            for value in subkey.values():
                                try:
                                    region_info[f"{subkey_path}\\{value.name()}"] = value.value()
                                    print(f"  Found: {value.name()} = {value.value()}")
                                except Exception as e:
                                    print(f"  Error reading {value.name()}: {str(e)}")
                    except Exception as e:
                        print(f"Error exploring {subkey.name()}: {str(e)}")
            except Registry.RegistryKeyNotFoundException:
                print(f"Key not found: {path}")

    # Check SYSTEM hive for TimeZoneInformation
    if os.path.exists(system_hive):
        reg = Registry.Registry(system_hive)
        try:
            key = reg.open(r"ControlSet001\Control\TimeZoneInformation")
            print("\nChecking TimeZoneInformation:")
            for value in key.values():
                try:
                    region_info[f"TimeZoneInformation\\{value.name()}"] = value.value()
                    print(f"  Found: {value.name()} = {value.value()}")
                except Exception as e:
                    print(f"  Error reading {value.name()}: {str(e)}")
        except Registry.RegistryKeyNotFoundException:
            print("TimeZoneInformation key not found in SYSTEM hive")

    # Special search for International settings
    if os.path.exists(software_hive):
        reg = Registry.Registry(software_hive)
        try:
            key = reg.open(r"Microsoft\Windows NT\CurrentVersion\GRE_Initialize")
            print("\nChecking GRE_Initialize:")
            for subkey in key.subkeys():
                if "Locale" in subkey.name():
                    print(f"  Found locale key: {subkey.name()}")
                    for value in subkey.values():
                        try:
                            region_info[f"GRE_Initialize\\{subkey.name()}\\{value.name()}"] = value.value()
                            print(f"    {value.name()} = {value.value()}")
                        except Exception as e:
                            print(f"    Error reading {value.name()}: {str(e)}")
        except Registry.RegistryKeyNotFoundException:
            print("GRE_Initialize key not found")

    # Specifically look for Control Panel International settings
    if os.path.exists(software_hive):
        reg = Registry.Registry(software_hive)
        international_paths = [
            r"Microsoft\Windows\CurrentVersion\Control Panel\International",
            r"Control Panel\International"
        ]

        for int_path in international_paths:
            try:
                key = reg.open(int_path)
                print(f"\nChecking {int_path}:")
                for value in key.values():
                    try:
                        region_info[f"{int_path}\\{value.name()}"] = value.value()
                        print(f"  Found: {value.name()} = {value.value()}")
                    except Exception as e:
                        print(f"  Error reading {value.name()}: {str(e)}")
            except Registry.RegistryKeyNotFoundException:
                print(f"Key not found: {int_path}")

    return region_info

if __name__ == "__main__":
    region_info = analyze_registry_for_region()

    # Summary of findings
    print("\n\n========== REGION INFORMATION SUMMARY ==========")
    print("Based on the registry analysis, the following region information was found:")

    # TimeZone is most important
    if any("TimeZone" in key for key in region_info.keys()):
        for key, value in region_info.items():
            if "TimeZone" in key:
                print(f"- {key}: {value}")

    # Look specifically for Singapore Standard Time
    if "TimeZoneInformation\\TimeZoneKeyName" in region_info and region_info["TimeZoneInformation\\TimeZoneKeyName"] == "Singapore Standard Time":
        print("\nThe system appears to be configured for Singapore Standard Time.")
        print("Region: Singapore")
    else:
        print("\nNo definitive region found. Check the above information for clues.")

